HTML=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta http-equiv="Cache-Control" content="no-store"><title>Fast Scalper Beta</title><style>
*{box-sizing:border-box}html,body{margin:0;background:#080e1b;color:#edf2ff;font-family:Arial,Helvetica,sans-serif}body{min-width:320px}.wrap{max-width:720px;margin:auto;padding:14px 25px 30px}.head{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:16px}.brand h1{margin:0;font-size:31px;font-weight:800;line-height:1}.bolt{font-size:42px;vertical-align:-5px;margin-right:7px}.sub{margin-top:8px;color:#8d98b1;font-size:18px}.online{display:flex;align-items:center;gap:8px;background:#073b39;color:#00e978;border-radius:14px;padding:10px 14px;font-weight:800;font-size:15px;white-space:nowrap}.dot{width:13px;height:13px;border-radius:50%;background:#00e978}.gear{font-size:30px;color:#aab8d4}.card{background:#111a2d;border:1px solid #273653;border-radius:24px;padding:24px;margin-bottom:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.metric{background:#0a1223;border-radius:17px;padding:16px;min-height:88px}.k{font-size:18px}.v{font-size:27px;font-weight:800;margin-top:4px;white-space:nowrap}.unit{font-size:16px;color:#91a0ba;font-weight:400;margin-left:5px}.modes{display:grid;grid-template-columns:1fr 1fr 1.15fr;gap:14px;margin-top:15px}.btn{height:54px;border:0;border-radius:15px;color:#fff;background:#245b91;font-size:17px;font-weight:800;padding:0 16px;cursor:pointer;white-space:nowrap}.paper{background:#293954}.green{background:#00a65a}.red{background:#c52f47}.gray{background:#293954}.note{margin-top:14px;color:#9ba5ba;font-size:17px}.label{font-size:13px;color:#8d98b1;font-weight:800;margin:0 0 5px}.inline{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr) minmax(0,1.15fr) minmax(0,.7fr);gap:9px;align-items:end}.group{min-width:0}.input{height:54px;width:100%;background:#091122;border:1px solid #30405e;border-radius:15px;color:#edf2ff;padding:0 15px;font-size:18px;outline:none}.profitrow{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;align-items:end;margin-top:13px}.profitgroup{min-width:0}.check{height:54px;display:flex;align-items:center;gap:8px;font-size:18px;white-space:nowrap}.check input{width:27px;height:27px;accent-color:#1676e8}.actions{display:grid;grid-template-columns:1.3fr 1fr .72fr;gap:10px;margin-top:13px}.off{display:flex;align-items:center;gap:14px;margin-top:10px}.off .btn{width:147px}.session{color:#9ba5ba;font-size:17px}.status{font-size:12px;color:#9ba5ba;min-height:14px;margin-top:3px}.title{font-size:30px;font-weight:800;margin:0 0 13px}.badge{display:inline-block;background:#c52f47;border-radius:14px;padding:7px 13px;font-size:13px;font-weight:800;margin-bottom:12px}.empty{color:#8d96a9;font-size:17px}.pos{display:flex;flex-direction:column;gap:8px}.item{font-size:14px;padding:9px 12px;background:#0a1223;border-radius:12px}.slots{display:grid;grid-template-columns:1fr 1fr;gap:9px}.slot{height:48px;background:#091122;border:1px solid #30405e;border-radius:13px;color:#edf2ff;padding:0 14px;font-size:16px;width:100%}.bottomnav{position:fixed;left:0;right:0;bottom:0;height:64px;background:#06101d;border-top:1px solid #273653;display:grid;grid-template-columns:repeat(5,1fr)}.nav{display:flex;flex-direction:column;align-items:center;justify-content:center;color:#91a2c0;font-size:11px;gap:2px}.nav.active{color:#1684ff}.ni{font-size:22px}@media(max-width:560px){.wrap{padding:0 25px 76px}.head{margin-bottom:10px}.brand h1{font-size:30px}.bolt{font-size:39px}.sub{font-size:16px}.online{font-size:13px;padding:8px 10px}.gear{font-size:25px}.card{padding:16px;margin-bottom:10px;border-radius:22px}.grid{gap:8px}.metric{padding:10px;min-height:73px}.k{font-size:17px}.v{font-size:25px}.unit{font-size:14px}.modes{gap:8px;margin-top:10px}.modes .btn{height:50px;font-size:14px;padding:0 5px}.note{font-size:15px;margin-top:9px}.control{padding-top:12px}.inline{grid-template-columns:1.05fr 1.05fr 1.05fr .72fr;gap:6px}.label{font-size:10px}.input{height:43px;font-size:16px;padding:0 9px}.inline .btn{height:43px;font-size:12px;padding:0 4px}.profitrow{gap:8px}.profitrow .input{height:43px}.check{height:43px;font-size:15px}.check input{width:19px;height:19px}.actions{gap:7px;margin-top:8px}.actions .btn{height:43px;font-size:13px;padding:0 4px}.off{gap:8px;margin-top:7px}.off .btn{width:95px;height:43px;font-size:14px}.session{font-size:14px}.title{font-size:28px}.badge{font-size:11px}.slot{height:43px;font-size:14px}.bottomnav{height:62px}}
</style></head><body><div class="wrap"><header class="head"><div class="brand"><h1><span class="bolt">⚡</span>Fast Scalper Beta</h1><div class="sub">Version 0.01 REPAIR PAPER · Trading TF: 3m</div></div><div style="display:flex;align-items:center;gap:12px"><div class="online"><span class="dot"></span>ONLINE</div><div class="gear">⚙</div></div></header>
<section class="card"><div class="grid"><div class="metric"><div class="k">Account Balance</div><div class="v"><span id="account">1850.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Bot Balance</div><div class="v"><span id="bot">0.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Reserve</div><div class="v"><span id="reserve">0.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Session PnL</div><div class="v"><span id="pnl">0.0000</span> <span class="unit">USDT</span></div></div></div><div class="modes"><button class="btn paper" onclick="setMode('PAPER')">PAPER</button><button class="btn" onclick="setMode('BINANCE_TEST')">BINANCE<br>TEST</button><button class="btn" onclick="testBinance()">TEST BINANCE</button></div><div class="note" id="note">Bot balance set: 0.0000 USDT</div></section>
<section class="card control"><div class="inline"><div class="group"><div class="label">BOT BALANCE · USDT</div><input id="allocation" class="input" inputmode="decimal" placeholder="150"></div><button class="btn" onclick="setAllocation()">SET BOT BALANCE</button><div class="group"><div class="label">WITHDRAW AMOUNT · USDT</div><input id="withdraw" class="input" inputmode="decimal" placeholder="0.00"></div><button class="btn red" onclick="doWithdraw()">WITHDRAW</button></div><div class="profitrow"><div class="profitgroup"><div class="label">PROFIT TARGET · %</div><input id="profit" class="input" inputmode="decimal" value="0.33"></div><label class="check"><input id="reinvest" type="checkbox" checked> Reinvest</label></div><div class="actions"><button class="btn green" onclick="startBot()">BOT ON · ACTIVE</button><button class="btn red" onclick="emergencyStop()">EMERGENCY</button><button class="btn gray" onclick="resetBot()">RESET</button></div><div class="off"><button class="btn red" onclick="stopBot()">BOT OFF</button><div class="session" id="session">SESSION 00:00 · 24H 00:00</div></div><div class="status" id="status"></div></section>
<section class="card"><div class="title">Open Positions</div><div id="badge" class="badge">BOT OFF · TRADING STOPPED</div><div class="pos" id="positions"><div class="empty">No open positions</div></div></section><section class="card"><div class="title">Rotation Pool · TOP-20</div><div class="slots" id="slots"></div></section></div><nav class="bottomnav"><div class="nav active"><div class="ni">⌂</div>Dashboard</div><div class="nav"><div class="ni">▥</div>Positions</div><div class="nav"><div class="ni">◎</div>Radar</div><div class="nav"><div class="ni">⚙</div>Settings</div><div class="nav"><div class="ni">▤</div>Logs</div></nav>
<script>
const $=id=>document.getElementById(id),num=x=>Number(x||0).toFixed(4),age=s=>{s=Math.max(0,Math.floor(Number(s||0)));return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')},api=async(p,o={})=>{const r=await fetch(p,{cache:'no-store',headers:{'Content-Type':'application/json',...(o.headers||{})},...o});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.detail||d.error||('HTTP '+r.status));return d},msg=t=>{$('status').textContent=t||''};
async function refresh(){try{const s=await api('/api/state');$('account').textContent=num(s.account);$('bot').textContent=num(s.bot_balance);$('reserve').textContent=num(s.reserve);$('pnl').textContent=num(s.session_realized);$('profit').value=Number(s.profit_pct??.33).toFixed(2);$('reinvest').checked=!!s.reinvest;$('session').textContent='SESSION '+age(s.session_age)+' · 24H '+age(s.day_age);$('note').textContent='Bot balance set: '+num(s.bot_balance)+' USDT';$('badge').textContent=s.running?'BOT ON · ACTIVE':'BOT OFF · TRADING STOPPED';drawSlots(s.slots||[]);drawPos(s.positions||[]);if(s.error)msg(s.error)}catch(e){msg(e.message)}}
function drawSlots(a){const e=$('slots');if(e.children.length!==20){e.innerHTML='';for(let i=0;i<20;i++){const x=document.createElement('input');x.className='slot';x.placeholder='USDT pair';x.onchange=saveSlots;e.appendChild(x)}}[...e.children].forEach((x,i)=>x.value=a[i]||'')}let saveTimer;function saveSlots(){clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{const a=[...$('slots').children].map(x=>x.value.trim().toUpperCase()).filter(Boolean);await api('/api/slots',{method:'POST',body:JSON.stringify({slots:a,profit_pct:Number($('profit').value.replace(',','.'))||.33,reinvest:$('reinvest').checked})});msg('Rotation Pool saved')}catch(e){msg(e.message)}},250)}
function drawPos(a){const e=$('positions');if(!a.length){e.innerHTML='<div class="empty">No open positions</div>';return}e.innerHTML=a.map(p=>'<div class="item"><b>'+p.symbol+'</b> · stake '+num(p.stake)+' · PnL '+num(p.delta_usdt)+' · '+age(p.age_seconds)+'</div>').join('')}
async function setMode(m){try{await api('/api/mode',{method:'POST',body:JSON.stringify({mode:m})});msg('Mode set: '+m);refresh()}catch(e){msg(e.message)}}async function testBinance(){try{const d=await api('/api/test-binance',{method:'POST'});msg(d.message||'Binance Testnet connection OK')}catch(e){msg(e.message)}}async function setAllocation(){try{await api('/api/allocation',{method:'POST',body:JSON.stringify({amount:Number($('allocation').value.replace(',','.'))})});msg('Bot balance set');refresh()}catch(e){msg(e.message)}}async function doWithdraw(){try{await api('/api/withdraw',{method:'POST',body:JSON.stringify({amount:Number($('withdraw').value.replace(',','.'))||0})});$('withdraw').value='';msg('Withdraw completed');refresh()}catch(e){msg(e.message)}}async function startBot(){try{await api('/api/paper/start',{method:'POST',body:JSON.stringify({profit_pct:Number($('profit').value.replace(',','.'))||0,reinvest:$('reinvest').checked})});msg('Bot active');refresh()}catch(e){msg(e.message)}}async function stopBot(){try{await api('/api/paper/stop',{method:'POST'});msg('Bot OFF — new entries stopped');refresh()}catch(e){msg(e.message)}}async function emergencyStop(){try{await api('/api/paper/emergency',{method:'POST'});msg('Emergency stop completed');refresh()}catch(e){msg(e.message)}}async function resetBot(){try{await api('/api/reset',{method:'POST'});msg('Reset completed');refresh()}catch(e){msg(e.message)}}refresh();setInterval(refresh,1000);
</script></body></html>'''

for r in list(legacy.app.router.routes):
    if getattr(r,'path',None)=='/' and 'GET' in (getattr(r,'methods',set()) or set()): legacy.app.router.routes.remove(r)
@legacy.app.get('/',response_class=HTMLResponse)
async def approved_ui_home():
    r=HTMLResponse(HTML);r.headers['Cache-Control']='no-store, no-cache, must-revalidate, max-age=0';r.headers['Pragma']='no-cache';r.headers['Expires']='0';return r
